action_details.action_postfix:
0.10 /parent_marginal_rate local
result.agi bracket_1_mfj <={
  0.10 /parent_marginal_rate local
} if
result.agi bracket_1_mfj > result.agi bracket_2_mfj <=and {
  0.12 /parent_marginal_rate local
} if
result.agi bracket_2_mfj > result.agi bracket_3_mfj <=and {
  0.22 /parent_marginal_rate local
} if
result.agi bracket_3_mfj > result.agi bracket_4_mfj <=and {
  0.24 /parent_marginal_rate local
} if
result.agi bracket_4_mfj > result.agi bracket_5_mfj <=and {
  0.32 /parent_marginal_rate local
} if
result.agi bracket_5_mfj > result.agi bracket_6_mfj <=and {
  0.35 /parent_marginal_rate local
} if
result.agi bracket_6_mfj > {
  0.37 /parent_marginal_rate local
} if
net_unearned_income parent_marginal_rate f* /dependent.kiddie_tax_amount xdef
"    Parent's marginal tax rate: " parent_marginal_rate 100 f* cvs strconcat "%" strconcat job.audit_trail swap addto
"    Kiddie tax amount: $" dependent.kiddie_tax_amount cvs strconcat job.audit_trail swap addto

